FactoryBot.define do
  factory :financial_event do
    user
    amount { Faker::Number.decimal(l_digits: 4, r_digits: 2) }
    currency { 'USD' }
    effective_date { Date.current }
    notes { Faker::Lorem.sentence }

    trait :income do
      event_type { 'income' }
      destination_money_account { association :money_account, user: user }
      source_money_account { nil }
    end

    trait :expense do
      event_type { 'expense' }
      source_money_account { association :money_account, user: user }
      destination_money_account { nil }
    end

    trait :transfer do
      event_type { 'transfer' }
      transient do
        shared_user { user }
      end
      source_money_account { association :money_account, user: shared_user }
      destination_money_account { association :money_account, user: shared_user }
    end

    trait :past_date do
      effective_date { 30.days.ago.to_date }
    end

    trait :future_date do
      effective_date { 30.days.from_now.to_date }
    end
  end
end
